**独立参考解答（非原书摘录）**

集合用**按字符升序、无重复结点的单链表**表示。读入时仅接纳 `a` 到 `z`；测试串中的数字和空格不属于题设元素，直接忽略。先用 `seen[26]` 去重，再按 `a` 至 `z` 尾插，得到有序链表，因而后续三个运算都可作归并扫描。

~~~c
typedef struct SNode { char ch; struct SNode *next; } SNode, *Set;

Set ReadSet(const char text[]) {
    bool seen[26] = {0};
    for (int i = 0; text[i] != 0; ++i)
        if ('a' <= text[i] && text[i] <= 'z') seen[text[i] - 'a'] = true;
    Set head = NULL, *tail = &head;
    for (int k = 0; k < 26; ++k) if (seen[k]) {
        *tail = NewNode('a' + k);
        tail = &(*tail)->next;
    }
    return head;
}

Set Union(Set p, Set q) {
    Set r = NULL, *tail = &r;
    while (p || q) {
        char x;
        if (!q || (p && p->ch < q->ch)) { x = p->ch; p = p->next; }
        else if (!p || q->ch < p->ch)   { x = q->ch; q = q->next; }
        else { x = p->ch; p = p->next; q = q->next; }
        *tail = NewNode(x); tail = &(*tail)->next;
    }
    return r;
}

Set Inter(Set p, Set q) {
    Set r = NULL, *tail = &r;
    while (p && q) {
        if (p->ch < q->ch) p = p->next;
        else if (q->ch < p->ch) q = q->next;
        else { *tail = NewNode(p->ch); tail = &(*tail)->next; p = p->next; q = q->next; }
    }
    return r;
}

Set Difference(Set p, Set q) {
    Set r = NULL, *tail = &r;
    while (p) {
        while (q && q->ch < p->ch) q = q->next;
        if (!q || p->ch < q->ch) { *tail = NewNode(p->ch); tail = &(*tail)->next; }
        else q = q->next;
        p = p->next;
    }
    return r;
}
~~~

归并时指针只前移，且每个输出字符都来自相应集合；相等分支只输出一次，故结果仍有序且无重复。三个运算均不改动两个操作数。若两表长度为 p、q，时间为 O(p+q)，结果空间为 O(p+q)。例如 `magazine` 与 `paper` 得到并集 `aegimnprz`、交集 `ae`、差集 `gimnz`；第二组测试按题设过滤非小写字符后得到 `adeinoprt`、`aeort`、`inp`。

