**独立参考解答（非原书摘录）**

以**带头结点的循环双向链表**表示万进制长整数。头结点的 `tag` 保存带符号的结点数；`head->next` 是最高组，`head->prior` 是最低组，每个元素结点保存 `0..9999`。规范零唯一表示为一个值为 0 的结点且 `tag=1`。这样一组加法的最大中间值为 `9999+9999+1=19999`，不超过题设 16 位整型上界 32767。

~~~c
#define BASE 10000
typedef struct DNode {
    int group;                 // 头结点为带符号组数，元素结点为 0..9999
    struct DNode *prior, *next;
} DNode, *LongInt;

/* 解析时先读符号；去掉逗号后，首组 1..4 位、其余组恰 4 位，均为十进制数字。
   从左到右在 head 前尾插，所以 next 方向始终是高位到低位。 */
int CompareAbs(LongInt a, LongInt b);
LongInt AddAbs(LongInt a, LongInt b) {
    LongInt r = NewEmptyHead();
    DNode *p = a->prior, *q = b->prior;
    int carry = 0, cnt = 0;
    while (p != a || q != b || carry) {
        int s = carry + (p != a ? p->group : 0) + (q != b ? q->group : 0);
        InsertAfterHead(r, s % BASE); // 从低位向高位计算，前插保持高位在前
        carry = s / BASE; ++cnt;
        if (p != a) p = p->prior;
        if (q != b) q = q->prior;
    }
    r->group = cnt; return r;
}

/* 前提 |a| >= |b|；与 AddAbs 同样自尾向前，borrow 为 0 或 1。 */
LongInt SubAbs(LongInt a, LongInt b) {
    LongInt r = NewEmptyHead();
    DNode *p = a->prior, *q = b->prior;
    int borrow = 0, cnt = 0;
    while (p != a) {
        int s = p->group - borrow - (q != b ? q->group : 0);
        if (s < 0) { s += BASE; borrow = 1; } else borrow = 0;
        InsertAfterHead(r, s); ++cnt;
        p = p->prior; if (q != b) q = q->prior;
    }
    RemoveLeadingZeroGroups(r, &cnt);
    r->group = cnt; return r;
}

LongInt Add(LongInt a, LongInt b) {
    int sa = Sign(a), sb = Sign(b);
    LongInt r;
    if (sa == sb) { r = AddAbs(a, b); SetSign(r, sa); }
    else if (CompareAbs(a, b) >= 0) { r = SubAbs(a, b); SetSign(r, sa); }
    else { r = SubAbs(b, a); SetSign(r, sb); }
    NormalizeZero(r);
    return r;
}
~~~

`CompareAbs` 先比绝对组数，再自最高组逐组比较；`RemoveLeadingZeroGroups` 不删除唯一的零组。`Add` 只读两个操作数，结果另建链表，因此不会破坏输入。输出时先按 `tag` 的符号印负号，再从 `next` 至 `head` 印第一组和补足四位的后续组。应核验：`-2345,6789 + -7654,3211 = -1,0000,0000`，`-9999,9999 + 1,0000,0000,0000 = 9999,0000,0001`，以及相反数相加规范为 `0`。设两数分别有 p、q 组，比较、加减和输出均为 O(p+q)，结果空间 O(max(p,q))，且没有位数上限。

