**独立参考解答（非原书摘录）**

停车场采用容量为 `n` 的**顺序栈**：栈底是最早到达、最北侧的车，栈顶是大门南侧的车；便道采用**带头尾指针的链队列**；另设同容量顺序栈 `temp` 作为让路栈。停车费率 `rate` 由输入给出，停车场计费时间只从真正入场时刻开始，便道等待不收费。每一车牌在停车栈和便道队列中必须唯一，事件时刻非递减。

~~~c
typedef struct { int plate, enter; } Car;
typedef struct { Car a[MAXN]; int top; } SqStack;
typedef struct Wait { int plate, arrive; struct Wait *next; } Wait;
typedef struct { Wait *front, *rear; } LinkQueue;

void Arrive(int plate, int t) {
    if (ExistsInPark(plate) || ExistsInWait(plate)) 报告重复车牌;
    else if (park.top < n) { Push(&park, (Car){plate, t}); 输出停车场位置(park.top); }
    else { EnQueue(&road, plate, t); 输出便道位置(QueueLength(road)); }
}

void Depart(int plate, int t) {
    if (!FindInPark(plate)) { 报告车辆不在停车场; return; }
    while (GetTop(park).plate != plate) { Pop(&park, &x); Push(&temp, x); }
    Pop(&park, &x);
    输出停留时间(t - x.enter), 应缴费用(rate * (t - x.enter));
    while (!StackEmpty(temp)) { Pop(&temp, &x); Push(&park, x); }
    if (!QueueEmpty(road)) {
        DeQueue(&road, &x);
        Push(&park, (Car){x.plate, t}); // 从此刻起才在车场内计费
        输出(x.plate, 已由便道进入停车场的位置, park.top);
    }
}
~~~

`FindInPark` 可只读顺序栈数组实现，或通过顺序栈基本操作复制到临时栈后恢复；其失败时不得改变状态。离车时，位于目标车之后的车辆依次压入 `temp`，目标车出栈后再反向弹回，故原先的相对次序完全恢复；空出的一个车位只允许便道队首进入。题给 `n=2` 的序列中：1 号在 5 入场、15 离场，停车 10；2 号在 10 入场、35 离场，停车 25；4 号在 25 到便道、因 2 号离场于 35 入场、40 离场，停车仅 5，随后 5 号入场。

一次到达为 O(1)（若重复检查另计）；离车最坏移动 O(n)，恢复后仍为 O(n)；便道链队列的入、出队为 O(1)。空间为 O(n+w)，w 为便道车辆数。结束事件 `E` 释放所有便道结点。

**独立参考解答（非原书摘录）**

用**链栈**保存尚待解释的字符，用**链队列**暂存一对括号内从左到右读到的字符。先将整句从右到左压栈，故每次弹出即为当前最左待处理符号。规则 `B -> tAdA` 与 `A -> sae` 的右部必须从右向左压栈，才能按从左到右继续解释。输入必须括号平衡，且每个括号组至少含一个首字符 θ；若遇孤立右括号、未闭合左括号或未知大写字母则报错。

~~~c
void PushRule(Stack *s, char x) {
    if (x == 'B') { Push(s,'A'); Push(s,'d'); Push(s,'A'); Push(s,'t'); }
    else if (x == 'A') { Push(s,'e'); Push(s,'a'); Push(s,'s'); }
    else 错误;
}

void ExpandParen(Stack *s) {
    Queue q; InitQueue(&q);
    while (!StackEmpty(*s) && GetTop(*s) != ')') { Pop(s,&x); EnQueue(&q,x); }
    if (StackEmpty(*s) || QueueLength(q) == 0) 错误;
    Pop(s,&x);                         // 丢弃匹配的右括号
    DeQueue(&q,&theta);                // 队列为 θ, δ1, ..., δn
    Push(s, theta);                    // 最后的 θ 先入栈
    while (!QueueEmpty(q)) {
        DeQueue(&q,&delta);
        Push(s, delta);
        Push(s, theta);
    }                                  // 栈顶至下依次为 θδnθ...θδ1θ
}

void Explain(const char input[]) {
    Stack s; InitStack(&s);
    for (int i = Length(input)-1; i >= 0; --i) Push(&s,input[i]);
    while (!StackEmpty(s)) {
        char x; Pop(&s,&x);
        if (x == 'A' || x == 'B') PushRule(&s,x);
        else if (x == '(') ExpandParen(&s);
        else if (x == ')') 错误;
        else if ('a' <= x && x <= 'z') 输出(x);
        else 错误;
    }
}
~~~

括号规则的入栈顺序可直接核验：队列为 `e,h,n,x,g,z` 时，先压最后的 `e`，再依次压 `h,e,n,e,x,e,g,e,z,e`，后续弹出正是 `e,z,e,g,e,x,e,n,e,h,e`。因此 `B(ehnxgz)B` 经两条字母规则和括号规则后为 `tsaedsaeezegexenehetsaedsae`。在本题给定两条规则下每次替换均减少一个大写符号或一对括号，故对合法有限输入终止；时间与栈、队列空间均为实际生成并处理的字符总数 O(T)。若扩展语法允许括号嵌套，应以深度计数先取出匹配括号组，再按相同规则递归/迭代展开。

**独立参考解答（非原书摘录）**

令 `S` 为调度站顺序栈、`O` 为输出序列顺序栈，输入尚未进入调度站的最小编号为 `next`。只通过 `InitStack`、`Push`、`Pop`、`StackEmpty` 等基本操作访问栈。每一状态有两条合法分支：若仍有输入则把 `next` 入 `S`；若 `S` 非空则将其栈顶出栈并压入 `O`。

~~~c
void PrintBottomToTop(SqStack *o) {
    SqStack t; InitStack(&t);
    while (!StackEmpty(*o)) { Pop(o,&x); Push(&t,x); }
    while (!StackEmpty(t)) { Pop(&t,&x); 输出(x); Push(o,x); }
}

void Enumerate(int next, int n, SqStack *s, SqStack *o) {
    if (next == n + 1 && StackEmpty(*s)) {
        PrintBottomToTop(o);
        输出换行;
        return;
    }
    if (next <= n) {
        Push(s, next);
        Enumerate(next + 1, n, s, o);
        Pop(s, &x);                   // 恢复调用前状态
    }
    if (!StackEmpty(*s)) {
        Pop(s, &x); Push(o, x);
        Enumerate(next, n, s, o);
        Pop(o, &x); Push(s, x);       // 恢复调用前状态
    }
}
~~~

初始为两个空栈和 `Enumerate(1,n,&S,&O)`，两栈容量均取 n。递归状态精确表示已输入、调度站和已输出三部分；两个分支穷尽且仅穷尽合法的下一步操作，回溯后完全恢复状态，所以每条叶路径都是一种可行输出，且所有可行输出均被枚举一次。`PrintBottomToTop` 用辅助栈而非直接访问顺序栈内部数组，打印后还原 `O`。

可核验地，n=1 有 1 种 `1`；n=2 有 2 种 `12,21`；n=3 有 5 种 `123,132,213,231,321`；n=4 有 14 种。总数为第 n 个 Catalan 数。输出本身已需 Θ(n·C_n) 个字符，枚举时间为 O(n·C_n)，递归与两栈的工作空间为 O(n)。

**独立参考解答（非原书摘录）**

采用显式顺序栈实现深度优先回溯，不能递归调用。`Board[8][8]` 初始全为 0；入栈帧 `(r,c,nextTry)` 表示马当前在 `(r,c)`，从 `HTry1/HTry2` 的 `nextTry` 号移动起尚未尝试。栈中从底到顶恰为当前路线，棋盘中的正数恰为该路线经过的步号。

~~~c
typedef struct { int r, c, nextTry; } Frame;
int dr[8] = {-2,-1,1,2,2,1,-1,-2};
int dc[8] = { 1, 2,2,1,-1,-2,-2,-1};

bool KnightTour(int si, int sj, int Board[8][8]) {
    if (si < 0 || si > 7 || sj < 0 || sj > 7) return false;
    Clear(Board);
    SqStack S; InitStack(&S);
    Board[si][sj] = 1; Push(&S, (Frame){si,sj,0});
    while (!StackEmpty(S)) {
        Pop(&S, &f);
        bool moved = false;
        for (int h = f.nextTry; h < 8; ++h) {
            int nr = f.r + dr[h], nc = f.c + dc[h];
            if (0 <= nr && nr < 8 && 0 <= nc && nc < 8 && Board[nr][nc] == 0) {
                f.nextTry = h + 1;
                Push(&S, f);                         // 保留余下候选位置
                Board[nr][nc] = StackLength(S) + 1;
                Push(&S, (Frame){nr,nc,0});
                if (StackLength(S) == 64) return true;
                moved = true; break;
            }
        }
        if (!moved) Board[f.r][f.c] = 0;             // 此位置的八种出路均已失败
    }
    return false;
}
~~~

可选地，在每帧首次生成合法候选后按其未访问后继数升序（Warnsdorff 次序）排列，能显著减少平均回溯；但仍要保留全部候选，不能因贪心失败就断言无解。每次前进把当前帧带着下一待试方向压回栈，失败时只撤销已经穷尽的帧，因此不会遗漏任何路线；深度达到 64 时每格恰填一次 1 至 64。最坏搜索时间为指数级，工作栈和棋盘空间均为 O(64)。输出前再检查数字 1..64 是否各出现一次，以及相邻步的坐标差是否为 `(±2,±1)` 或 `(±1,±2)`。

**独立参考解答（非原书摘录）**

以 `#` 为表达式首尾哨兵，设置运算符栈 `OPTR` 和数值栈 `OPND`。输入仅允许十进制整数、`+ - * / ( )` 和空白；本题的基本文法不含单目负号。读取到一个整数时一次性读完整个数字并压入 `OPND`，因此 `1024` 不会被误判为四个运算数。分号可作为一条表达式的结束符，等价于读入一个 `#` 后重新初始化两栈。

~~~c
Value Evaluate(const char expr[]) {
    Push(&OPTR, '#');
    for (Token t = NextToken(expr, true); ; t = NextToken(expr, true)) {
        if (t.kind == INTEGER) { Push(&OPND, ToValueChecked(t)); Trace(OPTR,OPND,t,压数); continue; }
        char in = (t.kind == END ? '#' : t.op);
        for (;;) {
            char top; GetTop(OPTR,&top);
            char rel = Precede(top, in); // 表 3.1：< 入栈，> 归约，= 配对
            if (rel == '<') { Push(&OPTR,in); Trace(OPTR,OPND,t,压算符); break; }
            if (rel == '=') { Pop(&OPTR,&top); Trace(OPTR,OPND,t,括号或哨兵匹配); break; }
            if (rel == '>') {
                Pop(&OPTR,&op);
                if (StackLength(OPND) < 2) 错误;
                Pop(&OPND,&right); Pop(&OPND,&left);
                if (op == '/' && right == 0) 错误;
                Push(&OPND, ApplyChecked(op,left,right));
                Trace(OPTR,OPND,t,归约);
                continue;
            }
            错误; // 非法相邻算符、括号不配对等
        }
        if (in == '#' && StackLength(OPTR) == 0) break;
    }
    if (StackLength(OPND) != 1) 错误;
    Pop(&OPND,&ans); return ans;
}
~~~

`Precede` 使用标准关系：栈顶为 `+/-` 时对 `* / (` 为 `<`、对 `+ - ) #` 为 `>`；栈顶为 `* /` 时仅对 `(` 为 `<`；`(` 对 `)` 为 `=`；`#` 对 `#` 为 `=`，其余未定义组合即非法。`ApplyChecked` 对加、减、乘、除检测数值溢出；若使用实数值类型，除法保留实数结果，若课程规定整型除法则显式采用截断规则。

每一步跟踪输出 `OPTR`、`OPND`、未读输入和操作名称。两个栈分别保存尚未归约的运算符和操作数，优先关系归约后保持与已读前缀等价；结束时唯一操作数即值。`3*(7-2)=15`，`3-3-3=-3`；`8/(9-9)` 在归约时报告除零。令 L 为字符数，扫描、压栈、弹栈次数均为 O(L)，额外空间 O(L)。

**独立参考解答（非原书摘录）**

采用事件驱动离散模拟。客户结点由 `malloc` 分配，含 `id,arr,dur,amount,next`；`amount<0` 表示取款/借款，`amount>0` 表示存款/还款。第一个服务队列 `Q1`、等候资金的队列 `Q2` 都是带头尾指针的链队列；事件表是按 `(time,seq)` 稳定排序的链表，事件为 `ARRIVE`、`DEPART`、`CLOSE`。`current` 非空表示唯一窗口忙。参数 `total, closetime, arrivalGap范围, duration范围, 正负金额范围` 均从终端读取；间隔、服务时长必须为正。

~~~c
void StartFirstIfIdle(int now) {
    while (current == NULL && !QueueEmpty(Q1)) {
        Customer *c = DeQueue(&Q1);
        if (c->amount < 0 && -c->amount > total) {
            EnQueue(&Q2,c);                 // 立刻转候补，不占用窗口服务时间
        } else {
            current = c;
            InsertEvent(now + c->dur, DEPART, c);
        }
    }
}

void ScanWaitingAfterDeposit(int now, long oldTotal) {
    int limit = QueueLength(Q2);             // 本次至多检查原有队列一遍
    while (limit-- > 0 && total > oldTotal && !QueueEmpty(Q2)) {
        Customer *c = DeQueue(&Q2);
        if (-c->amount <= total) {
            total += c->amount;              // amount 为负，立即满足并扣款
            Finish(c, now);                  // 累加 now-c->arr 后 free(c)
        } else EnQueue(&Q2,c);               // 保持未满足者的相对 FIFO 次序
    }
}

void HandleDeparture(Customer *c, int now) {
    long oldTotal = total;
    total += c->amount;                      // 正额存入，负额支出
    Finish(c,now); current = NULL;
    if (c->amount > 0) ScanWaitingAfterDeposit(now,oldTotal);
    StartFirstIfIdle(now);
}
~~~

处理 `ARRIVE` 时创建客户、入 `Q1`，若 `now+gap < closetime` 预置下一到达事件，再调用 `StartFirstIfIdle`。同一时刻先处理 `DEPART` 再处理 `ARRIVE`，使刚完成的业务和资金立即可见。处理正额离开后，`ScanWaitingAfterDeposit` 的两个停止条件严格对应题意：资金已降至本次存款前的 `oldTotal`，或 `Q2` 已完整检查一遍；后者防止所有剩余申请都无法满足时的无穷循环。

营业开始时插入首个 `ARRIVE` 和 `CLOSE(closetime)`。`CLOSE` 取消尚未发生的离开事件，把 `Q1`、`Q2` 和 `current` 中所有客户都以 `closetime-arr` 计入逗留时间后释放，且不再产生新到达。平均逗留时间为 `sumStay / finishedCount`；无客户时显示 N/A。事件表的时间顺序保证模拟时钟单调；任何客户只在 Q1、Q2、current 或完成态之一，且 `total` 始终等于初始资金加已完成业务金额。链式有序事件表插入最坏 O(E)，两队列入出队 O(1)，Q2 扫描按实际访问次数计；空间为在行客户和未处理事件数。

**独立参考解答（非原书摘录）**

系统把相对稳定的航班时刻表存为按 `flightNo`（并可建立按 `destination` 的辅助索引）有序的顺序表。为避免同一航班不同日期混用，运行期以 `(flightNo,date)` 定位一个具体 `FlightInstance`；其中有 `capacity,available,seatClass[1..capacity],occupied[]`，以及按姓名有序的已订客户链表和 FIFO 链式候补队列。初始化时必须录入每座位的舱位等级；若业务不限制舱位，可把所有座位标为通用等级，不能凭空假定各等级配额。

~~~c
Status Book(FlightInstance *f, const char *name, int k, int grade) {
    if (!f || k <= 0 || grade < 1 || grade > 3 || NameExists(f,name)) return ERROR;
    int seats[MAX_REQUEST], got = 0;
    for (int s = 1; s <= f->capacity && got < k; ++s)
        if (!f->occupied[s] && Compatible(f->seatClass[s],grade)) seats[got++] = s;
    if (got != k) return FULL_OR_INSUFFICIENT;
    for (int i = 0; i < k; ++i) f->occupied[seats[i]] = true;
    InsertBookedByName(f, name, k, grade, seats);
    f->available -= k; 输出座位号(seats,k);
    return OK;
}

void Cancel(FlightInstance *f, const char *name) {
    Booked *b = FindBooked(f,name);
    if (!b) { 输出未找到; return; }
    ReleaseSeats(f,b); f->available += b->count; DeleteBooked(f,b);
    int once = QueueLength(f->wait);
    while (once-- > 0 && !QueueEmpty(f->wait)) {
        Waiter *w = DeQueue(&f->wait);
        if (AskStillWants(w) && Book(f,w->name,w->count,w->grade) == OK) FreeWaiter(w);
        else EnQueue(&f->wait,w);
    }
}
